const RC=META.parts.length+1, QZ=RC+1, LS=RC+2, OUT=RC+3;

/* ---------- drawing helpers for this lesson (prefixed EF_ so they never clash with engine globals) ---------- */
const EF_F='font-family="Nunito Sans, sans-serif"';
const EF_T=(x,y,t,o={})=>`<text x="${x}" y="${y}" ${EF_F} font-size="${o.fs||24}" font-weight="${o.fw||600}" text-anchor="${o.a||'start'}" fill="${o.fill||'#18213A'}"${o.ex?' '+o.ex:''}>${t}</text>`;
const EF_L=(x1,y1,x2,y2,col='#5C6577',w=2,ex='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" ${ex}/>`;
const EF_box=(x,y,w,h,o={})=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${o.r??12}" fill="${o.fill||'#FFFFFF'}" stroke="${o.st||'#CED4DA'}" stroke-width="${o.sw??2}"${o.ex?' '+o.ex:''}/>`;
const EF_arrow=(x1,y1,x2,y2,col='#18213A',w=3)=>{const a=Math.atan2(y2-y1,x2-x1),h=16;return EF_L(x1,y1,x2-h*.6*Math.cos(a),y2-h*.6*Math.sin(a),col,w)+`<polygon points="${x2},${y2} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`};
const EF_sub=(a,b)=>`${a}<tspan baseline-shift="sub" font-size="70%">${b}</tspan>`;
const EF_GREY='#5C6577', EF_STEEL='#495057', EF_AL='#DEE2E6', EF_WALL='#343A40', EF_LEAN='#4C8DDB';
/* a port injector pointing down: body centred on x, nozzle tip at y; optional spray */
const EF_inj=(x,y,col=BLU,spray=true,s=1)=>`<rect x="${x-9*s}" y="${y-40*s}" width="${18*s}" height="${28*s}" rx="${4*s}" fill="${col}"/><polygon points="${x-6*s},${y-12*s} ${x+6*s},${y-12*s} ${x},${y}" fill="${col}"/>`+(spray?[[-10,14],[0,18],[10,14],[-6,26],[6,26]].map(([dx,dy])=>`<circle cx="${x+dx*s}" cy="${y+dy*s}" r="${3*s}" fill="${ORG}"/>`).join(''):'');
/* a small cylinder in section: walls x..x+w from y0 to y1, flat head, optional plug */
const EF_cyl=(x,y0,w,y1,o={})=>`${o.fill?`<rect x="${x}" y="${y0}" width="${w}" height="${y1-y0}" fill="${o.fill}" fill-opacity="${o.op??.3}"/>`:''}${EF_L(x,y0,x,y1,EF_WALL,5)}${EF_L(x+w,y0,x+w,y1,EF_WALL,5)}${EF_L(x-10,y0,x+w+10,y0,EF_WALL,7)}`+(o.plug?`<rect x="${x+w/2-7}" y="${y0-28}" width="14" height="26" rx="3" fill="${EF_GREY}"/>${EF_L(x+w/2,y0,x+w/2,y0+10,EF_WALL,4)}`:'');
/* an intake manifold: plenum bar, four runners down to four cylinders (fill opacities ops) */
const EF_manifold=(x,y,w,yc,ops,col=ORG)=>{const dx=w/4;let s=`<rect x="${x}" y="${y}" width="${w}" height="22" rx="8" fill="${EF_AL}" stroke="${EF_STEEL}" stroke-width="2.5"/>`;
 for(let i=0;i<4;i++){const cx=x+dx/2+i*dx;s+=`<rect x="${cx-9}" y="${y+22}" width="18" height="${yc-y-22}" fill="${EF_AL}" stroke="${EF_STEEL}" stroke-width="2"/>`+`<rect x="${cx-26}" y="${yc}" width="52" height="64" rx="6" fill="#FFFFFF" stroke="${EF_WALL}" stroke-width="3"/>`+`<rect x="${cx-23}" y="${yc+3}" width="46" height="58" rx="4" fill="${col}" fill-opacity="${ops[i]}"/>`}
 return s};
const EF_chip=(x,y,t,col,fs=22)=>{const w=Math.round(t.length*fs*.56+26);return `<rect x="${x}" y="${y}" width="${w}" height="${fs+16}" rx="${(fs+16)/2}" fill="${col}" fill-opacity=".14" stroke="${col}" stroke-width="2.5"/>`+EF_T(x+w/2,y+fs+2,t,{fs,fw:800,a:'middle',fill:col})};
/* a gauge dial with a value under it */
const EF_gauge=(x,y,r,t,col)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="#FFFFFF" stroke="${col}" stroke-width="4"/>`+EF_L(x,y,x+r*.55,y-r*.55,col,4)+`<circle cx="${x}" cy="${y}" r="5" fill="${col}"/>`+EF_T(x,y+r+28,t,{fs:22,fw:800,a:'middle',fill:col});
/* injector coil current i = I(1 - e^(-t/tau)), I proportional to the battery voltage: points for the answer picture */
const EF_curve=(I,x0,y0,W,H)=>{const pts=[];for(let k=0;k<=60;k++){const t=3*k/60;pts.push(`${(x0+t/3*W).toFixed(1)},${(y0-I*(1-Math.exp(-t))*H).toFixed(1)}`)}return pts.join(' ')};

